WITH filtered_store_sales AS (SELECT * FROM store_sales WHERE sale_date BETWEEN '2024-09-01' AND '2024-12-30' AND product_id IN (2, 3, 8)), summary AS (SELECT product_id, ROUND(STDDEV(revenue), 2) AS stddev_revenue, MAX(revenue) - MIN(revenue) AS revenue_range FROM filtered_store_sales GROUP BY product_id) SELECT product_id, stddev_revenue, revenue_range FROM summary WHERE stddev_revenue < 50 ORDER BY stddev_revenue DESC
